(() => {
  "use strict";
  const bank = {"facil":[["Qual acontecimento levou a Ordem Paranormal a investigar Heredistho?","O assassinato de Bárbara",["O roubo da Máscara do Desespero","Um incêndio na biblioteca","O desaparecimento de Veríssimo"],"A morte de Bárbara motivou a missão inicial."],["Quais agentes viajaram com Adrian para investigar a cidade?","Lyra e Hide",["Eclipse e Mikan","Juca e Dio","Vortex e Tainá"],"Lyra, Hide e Adrian formaram o grupo enviado à cidade."],["Qual jovem da Fazenda Andrade se juntou à investigação?","Calíope",["Layla","Juliana","Bárbara"],"Calíope Andrade passou a acompanhar os agentes."],["Com quem Calíope prometeu nunca se separar?","Juca",["Joaquim","Dio","Lázaro"],"Calíope e Juca fizeram essa promessa após a morte de Adrian."],["Em que criatura Bárbara se manifestou após a morte?","Zumbi de Sangue",["Esqueleto de Lodo","Cavalo de Lodo","Zumbi Bestial"],"O confronto com o Zumbi de Sangue de Bárbara aconteceu na casa de Joaquim."],["Quem morreu durante o confronto contra Azreal no corpo de Adrian?","Adrian",["Juca","Joaquim","Hide"],"Adrian morreu na batalha contra Azreal."],["Qual era o apelido de Dionathan?","Dio",["Juca","Hide","Azreal"],"Dionathan era chamado de Dio."],["Onde estava escondido o laboratório dos experimentos?","Sob a casa abandonada na floresta",["Na biblioteca","Sob o hotel","Na igreja"],"Os agentes abriram uma passagem subterrânea na casa abandonada."],["Quem venceu a partida de Xadrez Amaldiçoado?","Hide",["Lyra","Lázaro","Calíope"],"Lyra tentou primeiro, mas Hide venceu a partida."],["Quais criaturas atacaram o grupo durante o sepultamento de Manoel?","Esqueletos de Lodo",["Mesclas","Zumbis Amarelos","Cavalos de Lodo"],"Os Esqueletos de Lodo apareceram na clareira da floresta."],["Quem demonstrou interesse em treinar Calíope para a Ordem?","Veríssimo",["Dio","Francisco","Joaquim"],"Veríssimo ofereceu armas e mostrou interesse em treinar Calíope."],["Quem teve participação decisiva na derrota de CP01?","Calíope",["Layla","Dio","Otávio"],"Calíope foi fundamental para a vitória no confronto final."]],"medio":[["Em qual residência o rastreamento localizou o celular de Joaquim?","Na casa de Layla",["Na casa de Francisco","Na Fazenda Andrade","Na biblioteca"],"O sinal levou os agentes à residência de Layla."],["Que objeto Dio deixou com Calíope?","Um espelho de mão",["Um anel de caveira","Uma máscara","Uma katana"],"Dio entregou um pequeno espelho de mão a Calíope."],["Quem foi levada para jantar na Fazenda Andrade após sofrer uma agressão?","Layla",["Lyra","Juliana","Bárbara"],"Os agentes ajudaram Layla e a levaram para a fazenda."],["Que criaturas atacaram a Fazenda Andrade durante o incêndio no galpão?","Cavalos de Lodo",["Esqueletos de Lodo","Mesclas","Carniçais"],"Os Cavalos de Lodo atacaram enquanto o galpão queimava."],["Que lugar os agentes usaram para esconder Joaquim e interrogar Dio?","O barco de Carlos",["O hotel da Leylinha","A biblioteca","A igreja"],"O barco de Carlos foi utilizado como esconderijo."],["Em que local os agentes enfrentaram Juca para salvar Adrian?","Na clareira da árvore seca",["No galpão da fazenda","Na sala de segurança","Na igreja"],"O confronto aconteceu na clareira da árvore seca."],["O que foi encontrado após Lyra tocar a partitura no piano?","Um disco de vitrola",["Uma chave dourada","Um anel de caveira","Um revólver"],"A música abriu um compartimento secreto com o disco."],["Como foi aberta a passagem para o laboratório subterrâneo?","Reproduzindo o disco de vitrola",["Quebrando a porta","Usando uma chave de prata","Vencendo os Cavalos de Lodo"],"O disco encontrado após o enigma do piano abriu a entrada."],["O que atacou os agentes na casa de Joaquim, junto de um enorme portal?","Tentáculos",["Flores negras","Moscas de sangue","Cavalos de Lodo"],"Tentáculos surgiram do portal manifestado na residência."],["Quem forneceu o número de telefone necessário para rastrear Joaquim?","O velho Francisco",["Dio","Manoel","Veríssimo"],"Calíope e Adrian conseguiram o número conversando com Francisco."],["Quem morreu durante o confronto final contra CP01?","Lázaro",["Hide","Lyra","Joaquim"],"Lázaro perdeu a vida na batalha final."],["Que tipo de criatura estava acorrentada dentro da casa abandonada?","Um Zumbi Bestial",["Uma Mescla","Um Cavalo de Lodo","Um Manancial"],"O grupo eliminou um Zumbi Bestial acorrentado antes de investigar os documentos."]],"dificil":[["Qual era o nome da presença identificada como Número 1, que se revelou no corpo de Adrian?","Azreal",["Daraph","Geraldo","Dio"],"Azreal revelou sua presença e atacou Calíope na Fazenda Andrade."],["Por qual identificação era conhecido o poder despertado por Calíope diante de Dio?","CP12",["CP01","CP03","CP05"],"Calíope despertou seu poder de CP12 no confronto diante da casa abandonada."],["Sob o controle de que força CP01 matou irmãos e cientistas no laboratório?","A Aniquilação",["A Máscara do Desespero","O Grande Rei","O Paradoxo"],"As gravações mostraram CP01 sob controle da Aniquilação."],["Qual outro nome estava associado a Heredistho na revelação do ciclo temporal?","José",["Carlos","Geraldo","Francisco"],"O resumo relaciona Heredistho, também conhecido como José, ao ciclo criado pela viagem no tempo."],["Qual experimento Hide descobriu que ainda estava vivo e já tivera contato com os agentes?","CP05",["CP01","CP03","CP12"],"CP06 revelou a Hide que CP05 estava vivo e já havia encontrado o grupo."],["A observação de quem nas câmeras ajudou Lyra a descobrir uma senha?","Juliana",["Bárbara","Layla","Madalena"],"Lyra identificou a senha observando Juliana nas gravações."],["Quem revelou a forma de um gigantesco tornado negro no desfecho?","Daraph",["Azreal","CP06","A Aniquilação"],"Daraph revelou sua forma e levou a cidade através do tempo."],["Qual manifestação dos experimentos foi encontrada na área das celas?","O Existido de CP03",["A Mescla-Mãe","O Saci Pererê","O Rei Amarelo"],"Os investigadores encontraram o Existido de CP03 na área das celas."],["O que começou a acontecer quando o ciclo temporal foi rompido?","A realidade passou a se desfazer em miasma",["O céu ficou amarelo","Os mortos voltaram à vida","O laboratório virou uma igreja"],"O rompimento do ciclo fez a realidade de Heredistho se desfazer."],["Quem insistiu em acompanhar os agentes na descida ao laboratório?","Juca",["Joaquim","Veríssimo","Dio"],"Joaquim recebeu outra tarefa, enquanto Juca insistiu em descer com o grupo."],["O que houve de incomum no segundo Tic Tac de Calíope, na casa abandonada?","As badaladas não aconteceram",["As luzes do laboratório se apagaram","O piano começou a tocar sozinho","O céu ficou amarelo"],"Durante a visão sobre CP01, as badaladas habituais não aconteceram."],["Quem Veríssimo determinou que os agentes levassem vivo à base da Ordem?","Heredistho",["Dio","Juca","CP05"],"Veríssimo pediu que Heredistho fosse levado vivo à Ordem ao fim da missão."]]};
  const root = document.getElementById("quiz-heredistho");
  if (!root) return;

  const total = 10;
  const setup = document.getElementById("quiz-setup");
  const play = document.getElementById("quiz-play");
  const result = document.getElementById("quiz-result");
  const startButton = document.getElementById("quiz-start");
  const nextButton = document.getElementById("quiz-next");
  const replayButton = document.getElementById("quiz-replay");
  const levelButton = document.getElementById("quiz-change-level");
  const counter = document.getElementById("quiz-counter");
  const scoreLabel = document.getElementById("quiz-score");
  const progress = document.getElementById("quiz-progress");
  const questionText = document.getElementById("quiz-question");
  const answers = document.getElementById("quiz-options");
  const feedback = document.getElementById("quiz-feedback");
  const finalScore = document.getElementById("quiz-final-score");
  const finalTitle = document.getElementById("quiz-final-title");
  const finalSummary = document.getElementById("quiz-final-summary");

  let level = "facil";
  let questions = [];
  let position = 0;
  let points = 0;
  let answered = false;

  const shuffle = values => {
    const copy = values.slice();
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy;
  };

  function pickQuestions(difficulty) {
    return shuffle(bank[difficulty]).slice(0, total).map(([question, answer, wrong, explanation]) => ({
      question, answer, explanation,
      options: shuffle([answer, ...wrong])
    }));
  }

  function show(section) {
    setup.hidden = section !== "setup";
    play.hidden = section !== "play";
    result.hidden = section !== "result";
  }

  function renderQuestion() {
    const current = questions[position];
    answered = false;
    counter.textContent = `QUESTÃO ${position + 1} DE ${questions.length}`;
    scoreLabel.textContent = `${points} ACERTO${points === 1 ? "" : "S"}`;
    progress.style.width = `${Math.round(position / questions.length * 100)}%`;
    questionText.textContent = current.question;
    feedback.textContent = "";
    feedback.hidden = true;
    nextButton.hidden = true;
    answers.replaceChildren();

    current.options.forEach((option, index) => {
      const choice = document.createElement("button");
      choice.type = "button";
      choice.className = "quiz-answer";
      const letter = document.createElement("span");
      letter.className = "quiz-answer-letter";
      letter.textContent = String.fromCharCode(65 + index);
      const text = document.createElement("span");
      text.className = "quiz-answer-text";
      text.textContent = option;
      choice.append(letter, text);
      choice.addEventListener("click", () => answerQuestion(choice, option));
      answers.appendChild(choice);
    });
  }

  function answerQuestion(choice, selected) {
    if (answered) return;
    answered = true;
    const current = questions[position];
    const correct = selected === current.answer;
    if (correct) points++;

    for (const button of answers.querySelectorAll("button")) {
      button.disabled = true;
      if (button.querySelector(".quiz-answer-text").textContent === current.answer) {
        button.classList.add("is-correct");
      } else if (button === choice) {
        button.classList.add("is-incorrect");
      }
    }

    scoreLabel.textContent = `${points} ACERTO${points === 1 ? "" : "S"}`;
    feedback.textContent = `${correct ? "Resposta correta!" : "Resposta incorreta."} ${current.explanation}`;
    feedback.className = `quiz-feedback ${correct ? "is-correct" : "is-incorrect"}`;
    feedback.hidden = false;
    progress.style.width = `${Math.round((position + 1) / questions.length * 100)}%`;
    nextButton.textContent = position === questions.length - 1 ? "VER RESULTADO" : "PRÓXIMA QUESTÃO";
    nextButton.hidden = false;
    nextButton.focus();
  }

  function finish() {
    const percentage = Math.round(points / questions.length * 100);
    finalScore.textContent = `${percentage}%`;
    finalTitle.textContent = percentage >= 90 ? "Mestre dos Arquivos"
      : percentage >= 70 ? "Agente Veterano"
      : percentage >= 50 ? "Investigador Atento"
      : "Recruta da Ordem";
    finalSummary.textContent = `Você acertou ${points} de ${questions.length} questões no nível ${{
      facil: "Fácil", medio: "Médio", dificil: "Difícil"
    }[level]}.`;
    show("result");
    finalTitle.focus();
  }

  function start(difficulty) {
    level = difficulty;
    questions = pickQuestions(level);
    position = 0;
    points = 0;
    show("play");
    renderQuestion();
    questionText.focus();
  }

  startButton.addEventListener("click", () => {
    const selected = root.querySelector('input[name="quiz-level"]:checked');
    start(selected ? selected.value : "facil");
  });
  nextButton.addEventListener("click", () => {
    if (!answered) return;
    if (position === questions.length - 1) finish();
    else {
      position++;
      renderQuestion();
      questionText.focus();
    }
  });
  replayButton.addEventListener("click", () => start(level));
  levelButton.addEventListener("click", () => {
    show("setup");
    startButton.focus();
  });
})();
